'use strict';
const $=id=>document.getElementById(id),E=NotebookEngine;
const OPS={'+':['＋','たしざん'],'-':['−','ひきざん'],'*':['×','かけざん'],'/':['÷','わりざん']};
const SAMPLES={'+':[[27,15],[46,28],[268,157]],'-':[[52,28],[302,178],[73,46]],'*':[[23,14],[36,25],[23,4]],'/':[[72,3],[83,4],[125,8]]};
const STORE='hissan-full-notebook-v1';let storageOK=true,progress=0;
try{const saved=Number(localStorage.getItem(STORE));if(Number.isSafeInteger(saved)&&saved>=0)progress=saved;}catch{storageOK=false;}
let config={op:'+',example:0},lesson=null,strokes=[],recognized=null,result=null,phase='setup',guide=false,tool='pen',reviewTool='number',credited=false,version=0,history=[];
function picture(count){const stage=Math.min(4,Math.floor(count/3));return `<div class="progress-picture"><img class="reward-image" src="../assets/reward-island.jpg" alt="ふしぎな しまの ピクニック">${[0,1,2,3].map(i=>`<div class="mask" ${i<stage?'hidden':''}>？</div>`).join('')}</div>`;}
function status(s){$('notice').textContent=s;}
function save(){try{localStorage.setItem(STORE,String(progress));}catch{storageOK=false;}}
function refresh(focus=true){version++;drawing=false;$('notice').textContent='';if(phase==='setup')setup();else if(phase==='write')writing();else if(phase==='review')review();else finished();if(focus){window.scrollTo(0,0);$('app').setAttribute('tabindex','-1');$('app').focus({preventScroll:true});}if(!storageOK)$('app').insertAdjacentHTML('beforeend','<p class="status">このブラウザでは ごほうびを ほぞんできないよ。</p>');}
function setup(){const [a,b]=SAMPLES[config.op][config.example];$('app').innerHTML=`<section class="card"><h1>ひっさんを ぜんぶ かこう</h1><p class="sub">しきの したの しろいノートに、ペンや ゆびで かいてね。</p><div class="op-tabs">${Object.entries(OPS).map(([op,v])=>`<button data-op="${op}" aria-pressed="${op===config.op}"><b>${v[0]}</b><span>${v[1]}</span></button>`).join('')}</div><div class="intro-layout"><div><div class="example-row"><label for="sample">もんだい</label><select id="sample">${SAMPLES[config.op].map(([x,y],i)=>`<option value="${i}" ${i===config.example?'selected':''}>${x} ${OPS[config.op][0]} ${y}</option>`).join('')}</select></div><ol class="intro-list"><li>かずも、しるしも、せんも かこう。</li><li>とちゅうの けいさんも かこう。</li><li>よみとった ものを たしかめよう。</li><li>「これで さいてん」で たしかめるよ。</li></ol><p class="sub">よみとりを なおしても、ごほうびは へらないよ。</p></div><div class="preview-paper"><span>${a} ${OPS[config.op][0]} ${b} の したに じぶんで かこう</span></div></div><button class="primary start" id="start">ノートに かく →</button><div class="bottom-nav"><button id="book">📖 できたえほん（${Math.min(progress,12)} / 12もん）</button></div><p class="muted">ますめだけの、ふつうの ノートだよ。</p></section>`;
document.querySelectorAll('[data-op]').forEach(b=>b.onclick=()=>{config={op:b.dataset.op,example:0};refresh(false);});$('sample').onchange=()=>config.example=Number($('sample').value);$('start').onclick=()=>{const [a,b]=SAMPLES[config.op][config.example];lesson=buildLesson(config.op,a,b);strokes=[];history=[];recognized=null;result=null;credited=false;guide=false;tool='pen';phase='write';refresh();};$('book').onclick=()=>{phase='book';refresh();};}
function rowCount(){return Math.max(8,Math.max(...Object.values(lesson.finalCells).map(c=>c.row))+4);}
function toolbar(){return `<div class="toolbar"><button id="pen" aria-pressed="${tool==='pen'}">ペンで かく</button><button id="erase" aria-pressed="${tool==='erase'}">けしゴム</button><button id="undo" ${history.length?'':'disabled'}>ひとつ もどす</button><button id="guide" aria-pressed="${guide}">かく ばしょの ヒント</button></div>`;}
function canvasHTML(id='paper'){const rows=rowCount();return `<div class="canvas-wrap paper-grid" style="--rows:${rows}"><canvas id="${id}" width="432" height="${rows*72}" aria-label="ひっさんを ぜんぶ かく ノート。すうじは ひとマスに ひとつ、だんは マスに そろえてね"></canvas></div>`;}
function writing(){const r=rowCount();$('app').innerHTML=`<section class="card"><div class="top-row"><h1 class="equation">${lesson.equation} ＝ ？</h1><button id="back">← もんだいを えらぶ</button></div><p class="help"><strong>① したの ノートに、ひっさんを ぜんぶ かこう。</strong><br>すうじは ひとマスに ひとつ。だんは マスに そろえてね。</p>${toolbar()}<div class="work-layout"><div class="write-panel">${canvasHTML()}</div><aside class="side-note"><h2>かくもの</h2><p>・もんだいの かず<br>・＋ − × や わりざんの かたち<br>・けいさんの せん<br>・とちゅうの すうじ<br>・さいごの こたえ</p><p>くりあがり・くりさがりは、マスの うえに ちいさく かいてね。</p><p>ばしょに まよったら「かく ばしょの ヒント」を みてね。</p><button id="read" class="primary">ぜんぶ よみとる →</button><p class="muted">ここでは まだ さいてん しないよ。</p></aside></div><div class="status" id="read-status" role="status"></div><div class="actions"><button id="clear">ぜんぶ かきなおす</button><button id="read-bottom" class="primary">ぜんぶ よみとる →</button></div></section>`;
attachDrawing($('paper'));$('back').onclick=()=>{phase='setup';refresh();};$('pen').onclick=()=>{tool='pen';refresh(false);};$('erase').onclick=()=>{tool='erase';refresh(false);};$('undo').onclick=()=>{if(history.length)strokes=history.pop();refresh(false);};$('guide').onclick=()=>{guide=!guide;refresh(false);};$('clear').onclick=()=>{history.push(strokes.slice());strokes=[];refresh(false);};$('read').onclick=readAll;$('read-bottom').onclick=readAll;}
function renderStrokes(canvas,pending=null){const ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);if(guide&&phase==='write'){const expected=E.expected(lesson);ctx.strokeStyle='#d4aac0';ctx.fillStyle='#f6e7f080';ctx.setLineDash([3,5]);for(const k of Object.keys(expected.main)){const [r,c]=k.split(':').map(Number);ctx.fillRect(c*72+7,r*72+24,58,44);ctx.strokeRect(c*72+7,r*72+24,58,44);}for(const k of Object.keys(expected.notes)){const [r,c]=k.split(':').map(Number);ctx.strokeRect(c*72+12,r*72+2,48,18);}ctx.setLineDash([]);}ctx.strokeStyle='#4d4c4b';ctx.lineWidth=2.8;ctx.lineCap='round';ctx.lineJoin='round';for(const s of [...strokes,...(pending?[pending]:[])]){if(!s.length)continue;ctx.beginPath();ctx.moveTo(...s[0]);for(const p of s.slice(1))ctx.lineTo(...p);ctx.stroke();}}
let drawing=false;
function attachDrawing(canvas){renderStrokes(canvas);let pending=null,id=null;const epoch=version;
const point=e=>{const b=canvas.getBoundingClientRect();return [Math.max(0,Math.min(canvas.width,(e.clientX-b.left)*canvas.width/b.width)),Math.max(0,Math.min(canvas.height,(e.clientY-b.top)*canvas.height/b.height))];};
canvas.onpointerdown=e=>{if(id!==null||e.button>0)return;e.preventDefault();if(tool==='erase'){const p=point(e);const kept=strokes.filter(s=>!s.some(q=>Math.hypot(q[0]-p[0],q[1]-p[1])<18));if(kept.length!==strokes.length){history.push(strokes.slice());strokes=kept;}renderStrokes(canvas);$('undo')&&($('undo').disabled=!history.length);return;}id=e.pointerId;drawing=true;pending=[point(e)];canvas.setPointerCapture(id);};
canvas.onpointermove=e=>{if(id!==e.pointerId||!pending||epoch!==version)return;e.preventDefault();for(const v of (e.getCoalescedEvents?.()||[e])){const p=point(v);if(Math.hypot(p[0]-pending[pending.length-1][0],p[1]-pending[pending.length-1][1])>.4)pending.push(p);}renderStrokes(canvas,pending);};
const end=(e,cancel)=>{if(e.pointerId!==id)return;const s=pending;pending=null;id=null;drawing=false;if(!cancel&&s?.length>1&&epoch===version){history.push(strokes.slice());strokes.push(s);}if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);renderStrokes(canvas);if($('undo'))$('undo').disabled=!history.length;};canvas.onpointerup=e=>end(e,false);canvas.onpointercancel=e=>end(e,true);canvas.onlostpointercapture=e=>{if(e.pointerId===id)end(e,true);};canvas.oncontextmenu=e=>e.preventDefault();}
function readAll(){if(drawing){$('read-status').textContent='ペンを はなしてから おしてね。';return;}if(!strokes.length){$('read-status').textContent='まず ノートに ひっさんを かいてね。';return;}recognized=E.read(strokes,rowCount());if(!Object.keys(recognized.main).length&&!recognized.lines.length){$('read-status').textContent='うまく よめなかったよ。すうじを おおきく、マスに そろえて かいてみてね。';return;}result=null;phase='review';reviewTool='number';refresh();}
function normalizeText(v){return v.replace(/－|-/g,'−').replace(/[xX*ｘ]/g,'×').replace(/＋/g,'+').replace(/[０-９]/g,x=>String(x.charCodeAt(0)-0xff10));}
function reviewGrid(){const rows=rowCount();let html=`<div class="review-grid ${reviewTool==='number'?'':reviewTool==='note'?'edit-notes':'edit-lines'}" id="review-grid" style="--rows:${rows}">`;for(let r=0;r<rows;r++)for(let c=0;c<6;c++){const k=E.key(r,c),issue=result?.issues.some(x=>x.key===k);html+=`<div class="review-cell ${issue?'is-issue':''}"><input class="note" tabindex="${reviewTool==='note'?0:-1}" data-note="${k}" maxlength="2" inputmode="numeric" value="${escapeAttr(recognized.notes[k]||'')}" aria-label="うえから ${r+1}だんめ、ひだりから ${c+1}マスめの ちいさいすうじ"><input class="main" tabindex="${reviewTool==='number'?0:-1}" data-main="${k}" maxlength="1" value="${escapeAttr(recognized.main[k]||'')}" aria-label="うえから ${r+1}だんめ、ひだりから ${c+1}マスめの すうじ・しるし"></div>`;}html+=`<svg class="review-lines" viewBox="0 0 432 ${rows*72}" aria-hidden="true">${recognized.lines.map(l=>`<line x1="${l.start*72}" x2="${l.end*72}" y1="${l.row*72}" y2="${l.row*72}"></line>`).join('')}${recognized.brackets.map(b=>`<path d="M${b.col*72-14} ${b.row*72+3} Q${b.col*72+6} ${b.row*72+36} ${b.col*72-14} ${(b.row+1)*72-3}"></path>`).join('')}</svg><canvas class="line-canvas" id="line-canvas" width="432" height="${rows*72}" aria-label="よみとった せんを なおす ノート"></canvas></div>`;return html;}
function escapeAttr(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function review(){const issues=result?.issues||[];$('app').innerHTML=`<section class="card"><h1 class="equation">${lesson.equation} ＝ ？</h1><p class="help"><strong>② かいたものと、おなじか たしかめよう。</strong><br>${result?'よみとりが ちがったら、なんどでも なおせるよ。':'まだ さいてん していないよ。ちがう すうじは おして なおせるよ。'}<br>ちいさい すうじは マスの うえ、ふつうの すうじは しただよ。</p><div class="toolbar"><button id="edit-number" aria-pressed="${reviewTool==='number'}">すうじを なおす</button><button id="edit-note" aria-pressed="${reviewTool==='note'}">ちいさい すうじを なおす</button><button id="edit-line" aria-pressed="${reviewTool==='line'}">せんを なおす</button><button id="edit-bracket" aria-pressed="${reviewTool==='bracket'}">わりざんの かたち</button><button id="remove-line">せんを ひとつ けす</button></div><p class="sub">${reviewTool==='line'?'よみとった ノートの マスの さかいめに、せんを ひいてね。':reviewTool==='bracket'?'わられる かずの ひだりの さかいめを おしてね。':'＋は +、×は × か *、ひきざんは − か - で なおせるよ。'}</p><div class="review-columns"><div><h2 class="review-heading">じぶんで かいた ノート</h2>${canvasHTML('original')}</div><div><h2 class="review-heading">よみとった ノート（なおせるよ）</h2>${reviewGrid()}</div></div><div id="grade-status" class="status ${result?.ok?'good':''}" role="status">${result?.ok?'<h2>ぜんぶ できたね！ 🌸</h2><p>とちゅうの すうじも たしかめたよ。</p>':result?'<h2>もういちど たしかめよう</h2><p>よみとりが ちがうときは、すうじや せんを なおしてね。<br>けいさんを やりなおすときは「てがきに もどる」を おしてね。</p><ul class="issue-list">'+[...new Set(issues.map(x=>x.message))].map(m=>'<li>'+m+'</li>').join('')+'</ul><p class="muted">この おためしでは、だんを マスに そろえた かきかたで たしかめるよ。</p>':''}</div><div class="grade-controls"><button id="back-write">← てがきに もどる</button><button id="grade" class="primary">この ノートで さいてん</button>${result?.ok?'<button id="reward" class="primary">ごほうびの え →</button>':''}</div><p class="sub">よみとりを なおしても、ごほうびは へらないよ。</p></section>`;renderStrokes($('original'));
for(const type of ['main','note'])document.querySelectorAll(`[data-${type}]`).forEach(input=>input.oninput=()=>{const map=type==='main'?'main':'notes',k=input.dataset[type];const v=normalizeText(input.value).replace(type==='note'?/[^0-9?]/g:/[^0-9+−×?]/g,'');input.value=v;if(v)recognized[map][k]=v;else delete recognized[map][k];result=null;$('grade-status').textContent='なおした ノートで、もういちど さいてんできるよ。';if($('reward'))$('reward').disabled=true;});
$('edit-number').onclick=()=>{reviewTool='number';refresh(false);};$('edit-note').onclick=()=>{reviewTool='note';refresh(false);};$('edit-line').onclick=()=>{reviewTool='line';refresh(false);};$('edit-bracket').onclick=()=>{reviewTool='bracket';refresh(false);};$('remove-line').onclick=()=>{if(reviewTool==='bracket')recognized.brackets.pop();else recognized.lines.pop();result=null;refresh(false);};$('back-write').onclick=()=>{phase='write';result=null;refresh();};$('grade').onclick=()=>{result=E.grade(lesson,recognized,rowCount());refresh(false);$('grade-status').scrollIntoView({block:'nearest',behavior:'smooth'});};if($('reward'))$('reward').onclick=()=>{if(!result?.ok)return;if(!credited){progress++;credited=true;save();}phase='reward';refresh();};attachLineEditor();}
function attachLineEditor(){const canvas=$('line-canvas');let start=null,id=null;const pos=e=>{const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height};};canvas.onpointerdown=e=>{if(id!==null)return;e.preventDefault();id=e.pointerId;start=pos(e);canvas.setPointerCapture(id);};canvas.onpointerup=e=>{if(e.pointerId!==id)return;const end=pos(e);id=null;if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);if(reviewTool==='bracket')recognized.brackets.push({row:Math.max(0,Math.min(rowCount()-1,Math.floor(end.y/72))),col:Math.max(1,Math.min(5,Math.round(end.x/72)))});else{const left=Math.max(0,Math.floor(Math.min(start.x,end.x)/72)),right=Math.min(6,Math.ceil(Math.max(start.x,end.x)/72));if(right>left)recognized.lines.push({row:Math.max(0,Math.min(rowCount(),Math.round((start.y+end.y)/144))),start:left,end:right});}start=null;result=null;refresh(false);};canvas.onpointercancel=()=>{id=null;start=null;};}
function finished(){const count=progress%12===0&&progress>0?12:progress%12;$('app').innerHTML=`<section class="card"><h1>${phase==='reward'?'ひっさんを ぜんぶ がんばったね！':'わたしの できたえほん'}</h1><p class="sub">3もんで ひとつ、12もんで えが かんせいするよ。</p>${picture(count)}<p>${count} / 12もん ・ かんせい ${Math.floor(progress/12)}かい</p><div class="actions"><button id="setup" class="primary">べつの もんだいへ →</button>${lesson?'<button id="return">ノートに もどる</button>':''}</div></section>`;$('setup').onclick=()=>{phase='setup';refresh();};if($('return'))$('return').onclick=()=>{phase=recognized?'review':'write';refresh();};}
refresh(false);
